TModePair* __unguarded_partition(TModePair* first, TModePair* last, TModePair pivot, TModeLess comp)
{
    for (;;) {
        while (comp(*first, pivot))
            ++first;
        --last;
        while (comp(pivot, *last))
            --last;
        if (!(first < last))
            return first;
